{
  "interpretation": {
    "name": "Line2NutrunnerTighteningFixedTorqueRequest",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring the shared nutrunner NR7 to station st2 of line 2, tighten the fasteners, evaluate and record the result, then return and release the tool.",
    "constraints": [
      "The tool is exclusively reserved for line 2 for the whole use (reserve-tool before use, release-tool at the end).",
      "transport-tool to 'station' must complete before configure-tool or tighten-fasteners.",
      "The tightening program, including torque and tolerance, comes only from get-program (E4). The requested fixed 210 N*m cannot be written into the Recipe as a literal.",
      "The tightening must be evaluated and recorded (E5).",
      "Every tool-using step depends on the reserve-tool step so that the lease is renewed (E6)."
    ],
    "preference": "The operator prefers a fixed target torque of 210 N*m instead of the MES program. This conflicts with E4, so the Recipe keeps get-program and the preference is left to the validator and operator to resolve.",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": ["get-program"]
  },
  "recipe": {
    "name": "line2-nr7-tightening",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "MoveToStation",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "MoveToStation",
        "next": "Tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "Tighten",
        "next": "ReturnAndRelease",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten"],
            "dep": ["program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten",
            "service": "tighten-fasteners",
            "next": ["evaluate", "record"],
            "dep": ["configure", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "ReturnAndRelease",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
